(7286686, 1135771, 13077, '<td valign="top">Great lighting and color scheme for this one, also good concept.</td>', 'Great lighting and color scheme for this one, also good concept.', '2014-11-21 00:20:27.000000', NULL, 1),
(7286687, 1135773, 13077, '<td valign="top">Good use of tension-incurring crop, with odd shapes and funky processing thrown in for good measure. I don''t quite grasp the concept but it''s visually good and very interesting.</td>', 'Good use of tension-incurring crop, with odd shapes and funky processing thrown in for good measure. I don''t quite grasp the concept but it''s visually good and very interesting.', '2014-11-21 00:22:06.000000', NULL, 1),
